  // Step 5: Matching Request - match#age#town
  const performMatchSearch = async (ageRange, town) => {
    setIsSearching(true);
    try {
      const phone = currentUser?.phone || myPhone || '0712345678';

      // Try API first
      const result = await callApi('/match', 'POST', {
        phone: phone,
        ageRange: ageRange,
        town: town,
        offset: 0,
        limit: 10
      });

      if (result && result.status === 'success') {
        const matches = result.data?.matches || result.matches || [];
        const total = result.data?.total || result.total || 0;

        setMatchResults(matches);
        setTotalMatches(total);
        setMatchOffset(0);
        setMatchSearchActive(true);
        setHasMoreMatches(matches.length < total);

        // Add to SMS conversation
        const gender = 'ladies';
        addToConversation('📱 You', `match#${ageRange}#${town}`, false);
        addToConversation('🤖 System', SYSTEM_MESSAGES.matchFound(total, gender), true);

        // Show first 3 matches
        const firstThree = matches.slice(0, 3);
        addToConversation('🤖 System', SYSTEM_MESSAGES.matchList(firstThree), true);

        // Set matches for display
        setAllMatches(firstThree);

        if (matches.length > 0) {
          addNotification(`✅ Found ${matches.length} matches!`);
        } else {
          addNotification('🔍 No matches found. Try adjusting your criteria.', 'warning');
        }
      } else {
        // Fallback to sample data
        let filtered = SAMPLE_MATCHES;
        if (ageRange && ageRange !== '') {
          const [min, max] = ageRange.split('-').map(Number);
          if (!isNaN(min) && !isNaN(max)) {
            filtered = filtered.filter(m => m.age >= min && m.age <= max);
          }
        }
        if (town && town !== '') {
          filtered = filtered.filter(m => m.town.toLowerCase().includes(town.toLowerCase()));
        }

        const gender = filtered.length > 0 ? 'ladies' : 'people';
        addToConversation('📱 You', `match#${ageRange}#${town}`, false);
        addToConversation('🤖 System', SYSTEM_MESSAGES.matchFound(filtered.length, gender), true);

        const firstThree = filtered.slice(0, 3);
        addToConversation('🤖 System', SYSTEM_MESSAGES.matchList(firstThree), true);

        setMatchResults(filtered);
        setAllMatches(firstThree);
        setMatchSearchActive(true);
        setHasMoreMatches(filtered.length > 3);

        if (filtered.length > 0) {
          addNotification(`✅ Found ${filtered.length} matches!`);
        } else {
          addNotification('🔍 No matches found. Try adjusting your criteria.', 'warning');
        }
      }
    } catch (error) {
      console.error('Match search error:', error);
      addNotification('❌ Error searching matches.', 'error');
    } finally {
      setIsSearching(false);
    }
  };

