        console.error('Self-description error:', error);
        setRegistrationError('Network error. Please try again.');
        addNotification('❌ Network error', 'error');
        setIsLoading(false);
        return;
      }
    }

    // STEP 5: MATCHING REQUEST
    if (step === 5) {
      setIsLoading(true);
      try {
        const ageRange = formData.ageRange || '26-30';
        const town = formData.town || 'Nairobi';

        // Step 5: Matching Request - User to System
        addToConversation('📱 You', `match#${ageRange}#${town}`, false);

        // Perform match search
